                    3 to "The change feed lists changes, but it is not a restore feature.",
                ),
            ),
            B.q("sa-m2-33", "sa-backup-dr", "Blob backups must survive ransomware that deletes the whole storage account. Which Azure Backup option do you choose?", listOf("Operational backup for blobs", "Vaulted backup for blobs, to a Backup vault", "Blob soft delete alone", "Locally redundant storage"), setOf(1), "Vaulted backup copies blob data into a Backup vault, outside the storage account, so the copy survives if the account itself is deleted or encrypted. Operational backup keeps its data inside the source account.",
                scenario = "Inkwell Studio stores customer artwork uploaded from its Android drawing app in Blob Storage. The insurer asks for a copy that survives even if an attacker deletes the storage account.",
                whyWrong = mapOf(
                    0 to "Operational backup keeps its restore points in the same account, which goes with the account.",
                    2 to "Soft delete is inside the account too, and does not survive the account's deletion.",
                    3 to "LRS keeps three copies in one data centre of the same account. It is not a backup.",
                ),
            ),
            B.q("sa-m2-34", "sa-backup-dr", "The disaster recovery plan must be proved every quarter by bringing the app up in the secondary region, without touching production or stopping replication. What do you use in Azure Site Recovery?", listOf("A planned failover", "A test failover into an isolated virtual network", "A forced unplanned failover", "Disable replication, then fail over"), setOf(1), "A test failover starts copies of the VMs in the target region, in a network you choose that is cut off from production. Replication continues, and you clean up the test when you are done.",
                scenario = "Hawthorn Rail's ticketing back end for its Android app is protected by Site Recovery to a second region. The auditors want evidence of a working recovery every quarter with no impact on customers.",
                whyWrong = mapOf(
                    0 to "A planned failover moves production to the other region, which customers would notice.",
                    2 to "An unplanned failover is for a real disaster and moves production too.",
                    3 to "Disabling replication removes the protection you are trying to prove.",
                ),
            ),
            B.q("sa-m2-35", "sa-backup-dr", "An Azure file share must be backed up daily, kept for a year, and protected even if the storage account is lost. What do you recommend?", listOf("Share snapshots taken by hand", "Azure Backup for Azure Files with the vaulted backup tier, in a Recovery Services vault", "Soft delete for file shares", "Azure File Sync to an on-premises server"), setOf(1), "Azure Backup protects Azure file shares from a Recovery Services vault. The vaulted tier copies the data into the vault, so it survives loss of the account, with daily backups and long retention managed by a policy.",
                scenario = "Greystone Architects keeps project drawings on an Azure file share, which the firm's Android site-survey app also uploads to. Clients require a year of daily restore points held away from the share.",
                whyWrong = mapOf(
                    0 to "Manual snapshots stay in the same account and depend on someone remembering.",
                    2 to "Soft delete only brings back a deleted share for a short while. It is not a daily backup.",
                    3 to "File Sync keeps a cache in sync, so it copies deletions and corruption too.",
                ),
            ),
            B.q("sa-m2-36", "sa-backup-dr", "The Kubernetes cluster's workloads and their persistent volumes must be backed up and restorable to the same or another cluster. What do you recommend?", listOf("Azure Backup for AKS, using the backup extension and a Backup vault", "Back up the cluster's VMs with a VM backup policy", "Export the YAML files from the Git repository", "Take snapshots of the node OS disks"), setOf(0), "Azure Backup for AKS installs a backup extension in the cluster and stores backups through a Backup vault. It captures the cluster's resources and the disks behind persistent volumes, and restores into the same or a different cluster.",
                scenario = "Tidecaller runs the matchmaking service for its Android game on AKS. Some services keep state on persistent volumes, and a failed upgrade last month left the team rebuilding them by hand.",
                whyWrong = mapOf(
