            // Business continuity: high availability
            B.q("sa-m2-37", "sa-high-availability", "The production AKS cluster must survive the loss of a data centre and come with a financially backed uptime SLA for its API server. What do you configure? Select two.", listOf("Spread the node pools across availability zones", "Use the AKS Standard pricing tier", "Use the AKS Free pricing tier with more nodes", "Put all the nodes in a proximity placement group"), setOf(0, 1), "Nodes spread across availability zones keep pods running when one zone fails. The Standard tier adds a financially backed uptime SLA for the Kubernetes API server, which the Free tier does not have.",
                scenario = "Starling Pay's payments API for its Android wallet runs on AKS in one region. The contract with its banking partner demands an SLA on every component, and the cluster must ride out a zone failure.",
                whyWrong = mapOf(
                    2 to "The Free tier has no financially backed SLA, however many nodes you add.",
                    3 to "A proximity placement group packs VMs close together, which works against spreading them across zones.",
                ),
            ),
            B.q("sa-m2-38", "sa-high-availability", "An Azure Database for PostgreSQL flexible server must fail over automatically if its data centre fails, with no data loss. What do you configure?", listOf("A read replica in another region", "Zone-redundant high availability", "Same-zone high availability", "Daily geo-redundant backups"), setOf(1), "Zone-redundant high availability keeps a standby server in another availability zone, with every write committed to both before it is acknowledged. If the primary's zone fails, the standby takes over automatically with no data loss.",
                scenario = "Medlark Clinics' booking database for its Android appointment app runs on PostgreSQL flexible server. The region has availability zones, and a failed data centre must not stop bookings.",
                whyWrong = mapOf(
