            ),
            B.q("sa-m2-41", "sa-high-availability", "A web app and its Azure SQL database must keep working through a full regional outage with the least manual work, using one URL for users. What do you recommend? Select two.", listOf("Deploy the web app in two regions behind Azure Front Door", "Put the database in a failover group with a secondary in the second region, and connect through the failover group listener", "Use locally redundant backup storage", "Put both web apps in one availability set"), setOf(0, 1), "Front Door gives users one address and sends traffic to the healthy region. A failover group keeps a secondary database in the other region, and its listener name always points at the current primary, so the app's connection string does not change.",
                scenario = "Blackthorn Events' ticket API for its Android app runs in one region. A regional outage during a big concert sale cost it a day of sales, and it now wants a second region ready.",
                whyWrong = mapOf(
