            // Infrastructure: compute
            B.q("sa-m2-42", "sa-compute", "A containerised task must run every night at 02:00 and also whenever a message lands on a queue, run to completion, and cost nothing between runs, with no cluster to manage. What do you recommend?", listOf("Azure Container Apps jobs", "An AKS cluster with a CronJob", "An always-on VM with cron", "Azure App Service WebJobs"), setOf(0), "Container Apps jobs run containers that start, finish and stop. A job can be scheduled, triggered by events such as queue messages, or started by hand, and you pay only while it runs.",
                scenario = "Bramblewood's Android recipe app needs a nightly job that rebuilds search indexes and an on-demand job that resizes uploaded photos. Both are already container images, and the team has no Kubernetes skills.",
